// OpenAI returns choices[0].message.content
const llmText = $input.first().json.choices?.[0]?.message?.content ?? '[]';

let memories = [];
try {
  // Clean possible markdown backticks the LLM may add
  const clean = llmText.replace(/```json|```/gi, '').trim();
  memories = JSON.parse(clean);
  if (!Array.isArray(memories)) memories = [];
} catch(e) {
  memories = [];
}

// Filter: only importance >= 2, valid content
const filtered = memories
  .filter(m => m && m.content && (m.importance ?? 0) >= 2)
  .map(m => ({
    content:      String(m.content).substring(0, 200).trim(),
    importance:   Math.min(5, Math.max(1, parseInt(m.importance, 10) || 2)),
    category:     ['personal','preference','event','relationship'].includes(m.category)
                  ? m.category : 'personal',
    content_hash: $('Webhook Extract Memory').first().json.user_id
                  + ':' + String(m.content).substring(0, 50).toLowerCase().replace(/\s+/g,' ')
  }));

const userId = $('Webhook Extract Memory').first().json.user_id;

// n8n Code nodes NO pueden devolver [] vacío — causa Unknown error
if (filtered.length === 0) {
  return [{ json: { _no_memories: true } }];
}

return filtered.map(m => ({ json: { user_id: userId, ...m } }));
